11345: # The plugin's version (.claude-plugin/plugin.json next to this scripts directory), read once;
11346: # 'unknown' when it cannot be read.
11347: function Get-BridgeVersion {
11348:     if ($null -ne $script:BridgeVersion) { return $script:BridgeVersion }
11349:     $v = 'unknown'
11350:     try {
11351:         $mf = Join-Path (Join-Path (Split-Path -Parent $PSScriptRoot) '.claude-plugin') 'plugin.json'
11352:         if (Test-Path -LiteralPath $mf -PathType Leaf) {
11353:             $c = [string](Get-PropertyValue (ConvertFrom-Json -InputObject (Read-SharedText -Path $mf)) 'version' '')
11354:             if ($c -match '^[0-9A-Za-z][0-9A-Za-z.+-]{0,31}$') { $v = $c }
11355:         }
11356:     } catch { }
