11360: 
11361: # Where telemetry keeps its files, under the Codex home; $null without one. { Home; Spool (the
11362: # directory); Salt; Last (the last flush's result); Lock (the sender's lock); Notice (the marker of
11363: # the notice for this plugin version); NotSpooled (wave 28b, D6: the events not spooled, one NDJSON
11364: # line each - (wave 28e, E2) the LEGACY single file, still counted and folded); NotSpooledOwn (wave
11365: # 28e, E2: THIS process's file of them, telemetry-not-spooled-<pid>-<start ticks>.ndjson); (wave 28c,
11366: # D3) TelLock (THE telemetry lock of the producers, the salt's creation and -Forget) and Forgetting (the
11367: # marker -Forget writes while it deletes) }.
11368: function Get-TelemetryPaths {
11369:     $h = Get-CodexHome
11370:     if (-not $h) { return $null }
11371:     $spool = Join-Path $h 'telemetry-spool'
11372:     return [pscustomobject]@{
11373:         Home          = $h
11374:         Spool         = $spool
11375:         Salt          = (Join-Path $h 'telemetry-salt')
11376:         Last          = (Join-Path $spool '.last')
11377:         Lock          = (Join-Path $spool '.flush.lock')
11378:         Notice        = (Join-Path $h ('telemetry-notice-' + (Get-BridgeVersion)))
11379:         NotSpooled    = (Join-Path $h 'telemetry-not-spooled.ndjson')
11380:         NotSpooledOwn = (Join-Path $h "telemetry-not-spooled-$PID-$(Get-TelemetryOwnStartTicks).ndjson")
11381:         TelLock       = (Join-Path $h 'telemetry.lock')
11382:         Forgetting    = (Join-Path $h 'telemetry-forgetting')
11383:     }
11384: }
11385: 
11386: # (wave 28e, E2) This process's start time in ticks (Get-ProcessStartTicks), read once; 0 when it
11387: # cannot be read (its not-spooled file then names no start: its identity counts as unknown).
11388: $script:TelemetryOwnStartTicks = $null
11389: function Get-TelemetryOwnStartTicks {
11390:     if ($null -eq $script:TelemetryOwnStartTicks) {
11391:         $t = Get-ProcessStartTicks -ProcessId $PID
11392:         $script:TelemetryOwnStartTicks = $(if ($null -ne $t -and $t -gt 0) { [long]$t } else { [long]0 })
11393:     }
11394:     return $script:TelemetryOwnStartTicks
11395: }
11396: 
11397: # (wave 28c, D3 / F42-3) THE telemetry lock <codex home>/telemetry.lock - taken by every spool append
11398: # of a producer (Add-TelemetryEvent, a complaint kept), by the salt's creation and by -Forget -Local:
11399: # an OPEN HANDLE (FileShare.None), so the OS releases it when its holder dies (it is never stale; the
11400: # empty file stays). While -Forget holds it, the marker <codex home>/telemetry-forgetting says so; a
11401: # producer that meets the marker (or a lock that stays busy past its short wait) drops its event -
11402: # counted - instead of recreating the salt or the spool. (wave 28d, D2 / F48-2) The marker HEALS
11403: # itself: it names its owner {pid, start_time, (wave 28e, E3) start_ticks, since}; -Forget removes it
11404: # in `finally`; a marker whose
11405: # owner lives (Test-PidAlive - an identity that cannot be confirmed counts as living) refuses as
11406: # before, and one whose owner is gone - or that names none: -Forget writes it under this lock, so no
11407: # -Forget is writing it while it is held - is REMOVED under the lock (one line in <spool>/.last
11408: # `notes`, Resolve-TelemetryForgetting) and the holder goes on. Re-entrant within a process.
11409: # -IgnoreMarker: -Forget's own entry (it replaces a marker left behind), the spool's rewrite and the
11410: # notes of .last. { Ok; Why; Forgetting }.
11411: $script:TelemetryLockStream = $null
11412: $script:TelemetryLockDepth = 0
11413: function Enter-TelemetryLock {
11414:     param([int]$WaitMs = 1000, [switch]$IgnoreMarker)
11415:     $r = [pscustomobject]@{ Ok = $false; Why = ''; Forgetting = $false }
11416:     $p = Get-TelemetryPaths
11417:     if (-not $p) { $r.Why = 'no codex home (CODEX_HOME, else ~/.codex)'; return $r }
11418:     if ($script:TelemetryLockStream) {
11419:         if (-not $IgnoreMarker) { $why = Resolve-TelemetryForgetting -Paths $p; if ($why) { $r.Forgetting = $true; $r.Why = $why; return $r } }
11420:         $script:TelemetryLockDepth++
11421:         $r.Ok = $true
11422:         return $r
11423:     }
11424:     try { [void][IO.Directory]::CreateDirectory($p.Home) } catch { $r.Why = "the codex home $($p.Home) could not be made ($(ConvertTo-OneLine $_.Exception.Message))"; return $r }
11425:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
11426:     $fs = $null
11427:     while ($null -eq $fs) {
11428:         # a marker whose owner lives refuses at once (that -Forget holds this lock while it deletes)
11429:         if (-not $IgnoreMarker -and [IO.File]::Exists($p.Forgetting)) {
11430:             $m = Get-TelemetryForgettingOwner -Path $p.Forgetting
11431:             if ($m.Alive) { $r.Forgetting = $true; $r.Why = $m.Why; return $r }
11432:         }
11433:         try { $fs = New-Object System.IO.FileStream($p.TelLock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None) } catch {
11434:             if ($watch.ElapsedMilliseconds -ge $WaitMs) { $r.Why = "the telemetry lock $($p.TelLock) stayed busy for $([Math]::Round($WaitMs / 1000.0, 1)) s"; return $r }
11435:             Start-Sleep -Milliseconds 25
11436:         }
11437:     }
11438:     $script:TelemetryLockStream = $fs
11439:     $script:TelemetryLockDepth = 1
11440:     # the marker again, under the lock: a -Forget that finished removed it; (wave 28d, D2) one whose
11441:     # owner is gone is removed now, one whose owner lives refuses
11442:     if (-not $IgnoreMarker) {
11443:         $why = Resolve-TelemetryForgetting -Paths $p
11444:         if ($why) { Exit-TelemetryLock; $r.Forgetting = $true; $r.Why = $why; return $r }
11445:     }
11446:     $r.Ok = $true
11447:     return $r
11448: }
11449: 
11450: # Releases the telemetry lock (the last of a re-entrant holder's calls closes the handle).
11451: function Exit-TelemetryLock {
11452:     if (-not $script:TelemetryLockStream) { return }
11453:     $script:TelemetryLockDepth--
11454:     if ($script:TelemetryLockDepth -gt 0) { return }
11455:     try { $script:TelemetryLockStream.Dispose() } catch { }
11456:     $script:TelemetryLockStream = $null
11457:     $script:TelemetryLockDepth = 0
11458: }
11459: 
11460: # (wave 28d, D2 / F48-2) The forgetting marker as it is - read only: { There; Pid; Since; Alive (its
11461: # owner - pid and start time - lives, or its identity cannot be confirmed: Test-PidAlive, never
11462: # removed on a guess; a marker that names no owner is not alive); Why (the refusal while it lives) }.
11463: # (wave 28e, E3 / F54-3) A marker that records `start_ticks` (the owner's start time in ticks, 100 ns -
11464: # what -Forget writes since wave 28e) is judged on pid AND those ticks (Get-PidIdentityTicks: exactly
11465: # equal on Windows; 'unknown' counts as alive); an older marker without them by its start_time string
11466: # as before.
11467: function Get-TelemetryForgettingOwner {
11468:     param([string]$Path)
11469:     $m = [pscustomobject]@{ There = $false; Pid = 0; Since = ''; Alive = $false; Why = '' }
11470:     if (-not [IO.File]::Exists($Path)) { return $m }
11471:     $m.There = $true
11472:     $o = $null
11473:     try { $t = [string](Read-SharedText -Path $Path); if ($t.Trim().StartsWith('{')) { $o = ConvertFrom-JsonKeepOffset -Text $t } } catch { $o = $null }
11474:     $n = Get-TelemetryCount (Get-PropertyValue $o 'pid' $null)
11475:     if ($null -ne $n -and $n -le [int]::MaxValue) { $m.Pid = [int]$n }
11476:     $m.Since = [string](ConvertTo-JsonText (Get-PropertyValue $o 'since' ''))
11477:     $ticks = Get-TelemetryCount (Get-PropertyValue $o 'start_ticks' $null)
11478:     if ($m.Pid -gt 0 -and $null -ne $ticks -and $ticks -gt 0) { $m.Alive = [bool]((Get-PidIdentityTicks -ProcessId $m.Pid -StartTicks ([long]$ticks)) -ne 'gone') }
11479:     elseif ($m.Pid -gt 0) { $m.Alive = [bool](Test-PidAlive -ProcessId $m.Pid -StartTime ([string](ConvertTo-StartIso (Get-PropertyValue $o 'start_time' '')))) }
11480:     $m.Why = "codex-telemetry.ps1 -Forget -Local is deleting the local telemetry data (pid $($m.Pid)$(if ($m.Since) { ", since $($m.Since)" }); the marker $Path)"
11481:     return $m
11482: }
11483: 
11484: # (wave 28d, D2) UNDER the telemetry lock: a forgetting marker whose owner is gone (or that names none)
11485: # is removed - one line in <spool>/.last `notes` - and '' is returned (the holder goes on); a marker
11486: # whose owner lives returns the refusal. '' without a marker.
11487: function Resolve-TelemetryForgetting {
11488:     param($Paths)
11489:     $m = Get-TelemetryForgettingOwner -Path $Paths.Forgetting
11490:     if (-not $m.There) { return '' }
11491:     if ($m.Alive) { return $m.Why }
11492:     try { [IO.File]::Delete($Paths.Forgetting) } catch { return "the forgetting marker $($Paths.Forgetting) of a -Forget -Local that is gone could not be removed ($(ConvertTo-OneLine $_.Exception.Message))" }
11493:     Add-TelemetryLastNote -Text "removed the forgetting marker of $(if ($m.Pid -gt 0) { "pid $($m.Pid) (gone)" } else { 'no named owner' })$(if ($m.Since) { " since $($m.Since)" }) - a -Forget -Local that did not finish; run it again to finish the local deletion"
11494:     return ''
11495: }
