11497: # The intake's base URL: CODEX_CONSULT_TELEMETRY_URL (an operator setting), else
11498: # https://xelth.com/T. Only https - (wave 28b, D4 / F36-9, F37-4) plain http only for a LOOPBACK host
11499: # (127.0.0.1, localhost, ::1) AND with CODEX_CONSULT_TEST_MODE=1 (a harness's local intake). { Base
11500: # (no trailing slash; '' when refused); Source; Error }.
11501: function Get-TelemetryUrl {
11502:     $raw = ([string][Environment]::GetEnvironmentVariable('CODEX_CONSULT_TELEMETRY_URL')).Trim()
11503:     $src = 'CODEX_CONSULT_TELEMETRY_URL'
11504:     if (-not $raw) { $raw = $script:TelemetryDefaultUrl; $src = 'the default' }
11505:     $r = [pscustomobject]@{ Base = ''; Source = $src; Error = '' }
11506:     $u = $null
11507:     if (-not [Uri]::TryCreate($raw, [UriKind]::Absolute, [ref]$u) -or -not $u.Host) {
11508:         $r.Error = "the intake URL '$raw' ($src) is not an absolute URL"
11509:         return $r
11510:     }
11511:     if ($u.Scheme -ne 'https') {
11512:         if (-not ($u.Scheme -eq 'http' -and $u.IsLoopback)) {
11513:             $r.Error = "the intake URL '$raw' ($src) is refused: only https (plain http only for a loopback test intake in test mode)"
11514:             return $r
11515:         }
11516:         if (-not (Test-TestMode)) {
11517:             $r.Error = "the intake URL '$raw' ($src) is refused: plain http to a loopback intake only with CODEX_CONSULT_TEST_MODE=1 (a harness); a real intake is https"
11518:             return $r
11519:         }
11520:     }
11521:     $r.Base = $raw.TrimEnd('/')
11522:     return $r
11523: }
