11525: # The instance id: the lowercase hex SHA-256 of the 32 salt bytes followed by the UTF-8 bytes of
11526: # the machine name - the machine name never leaves in clear, and a new salt makes a new instance.
11527: # The salt: <codex home>/telemetry-salt, 64 lowercase hex digits, created ONCE (-Create). (wave 28b,
11528: # D5 / F36-9) Created atomically: a new salt is written to a temporary file and MOVED into place
11529: # without overwriting - a creator that loses the race reads the winner's salt; a salt that parses is
11530: # never deleted or replaced. A salt that does not parse is moved ASIDE (telemetry-salt.bad-<guid>,
11531: # kept) before a new one is made - and moved back when it turns out to parse after all (another
11532: # creator's salt that arrived in between). '' without a salt (and not -Create) or when it cannot be
11533: # made. (wave 28c, D3) -Create makes a salt only UNDER THE TELEMETRY LOCK (Enter-TelemetryLock, at
11534: # most $WaitMs; re-entrant for a producer that holds it) and never while -Forget deletes: '' then.
11535: function Read-TelemetrySalt {
11536:     param([string]$Path)
11537:     try { if ([IO.File]::Exists($Path)) { $t = (Read-SharedText -Path $Path).Trim(); if ($t -cmatch '^[0-9a-f]{64}$') { return $t } } } catch { }
11538:     return ''
11539: }
11540: function Get-TelemetryInstanceId {
11541:     param([switch]$Create, [int]$WaitMs = 2000)
11542:     $p = Get-TelemetryPaths
11543:     if (-not $p) { return '' }
11544:     $hex = Read-TelemetrySalt -Path $p.Salt
11545:     if (-not $hex) {
11546:         if (-not $Create) { return '' }
11547:         $lk = Enter-TelemetryLock -WaitMs $WaitMs
11548:         if (-not $lk.Ok) { return '' }
11549:         try {
11550:             $hex = Read-TelemetrySalt -Path $p.Salt
11551:             if (-not $hex) { $hex = New-TelemetrySalt -Paths $p }
11552:         } finally { Exit-TelemetryLock }
11553:         if (-not $hex) { return '' }
11554:     }
11555:     $salt = New-Object byte[] 32
11556:     for ($i = 0; $i -lt 32; $i++) { $salt[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
11557:     $name = $script:Utf8NoBom.GetBytes([string][Environment]::MachineName)
11558:     $all = New-Object byte[] ($salt.Length + $name.Length)
11559:     [Array]::Copy($salt, 0, $all, 0, $salt.Length)
11560:     [Array]::Copy($name, 0, $all, $salt.Length, $name.Length)
11561:     return (Get-Sha256Hex -Bytes $all)
11562: }
11563: 
11564: # The salt's creation (the caller holds the telemetry lock): the hex salt, '' when it cannot be made.
11565: function New-TelemetrySalt {
11566:     param($Paths)
11567:     $p = $Paths
11568:     $hex = ''
11569:     try {
11570:         [void][IO.Directory]::CreateDirectory($p.Home)
11571:         for ($round = 0; $round -lt 3 -and -not $hex; $round++) {
11572:             if ([IO.File]::Exists($p.Salt)) {
11573:                 # a salt that does not parse: moved aside (never deleted), then checked - one that
11574:                 # parses after all (a racing creator's) goes back when the place is still free
11575:                 $hex = Read-TelemetrySalt -Path $p.Salt
11576:                 if ($hex) { break }
11577:                 $aside = "$($p.Salt).bad-$([guid]::NewGuid().ToString('N'))"
11578:                 try { [IO.File]::Move($p.Salt, $aside) } catch { Start-Sleep -Milliseconds 50; continue }
11579:                 if (Read-TelemetrySalt -Path $aside) {
11580:                     try { [IO.File]::Move($aside, $p.Salt) } catch { }
11581:                     continue
11582:                 }
11583:             }
11584:             $bytes = New-Object byte[] 32
11585:             $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
11586:             try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
11587:             $tmp = "$($p.Salt).$([guid]::NewGuid().ToString('N')).tmp"
11588:             Write-Utf8NoBom -Path $tmp -Text ((ConvertTo-HexString $bytes) + "`n")
11589:             # moved into place only when absent: a salt another run moved there first wins
11590:             try { [IO.File]::Move($tmp, $p.Salt) } catch { try { [IO.File]::Delete($tmp) } catch { } }
11591:             $hex = Read-TelemetrySalt -Path $p.Salt
11592:         }
11593:     } catch { return '' }
11594:     return $hex
11595: }
