12420: # One request to the intake (POST with a JSON body; DELETE for -Forget): a TCP connect probe of at
12421: # most $ConnectMs (the proxy's address when the system proxy is used for the URL), then the request.
12422: # (wave 28b, D2 / F36-2) $TotalMs bounds the WHOLE request - the probe, the connection, sending the
12423: # body and reading the answer (HttpClient with the answer buffered inside its timeout, a cancel at
12424: # the bound, and a hard wait of the bound): a slow or trickling intake costs at most $TotalMs.
12425: # Delivered only on a 2xx answer that is a JSON object with "ok": true - anything else (a timeout,
12426: # an HTML page, a 4xx/5xx, a JSON without ok) is not delivered. { Delivered; Status (0: no HTTP
12427: # answer); Json; Text (the answer, at most 64 K characters); Why; RetryAfter (seconds; -1 when not
12428: # given) }.
12429: $script:TelemetryHttpReady = $false
12430: function Invoke-TelemetryRequest {
12431:     param([string]$Url, [string]$Body = '', [string]$Method = 'POST', [int]$ConnectMs = 3000, [int]$TotalMs = 8000)
12432:     $r = [pscustomobject]@{ Delivered = $false; Status = 0; Json = $null; Text = ''; Why = ''; RetryAfter = -1 }
12433:     $watch = [System.Diagnostics.Stopwatch]::StartNew()
12434:     $boundText = "$([Math]::Round($TotalMs / 1000.0, 1)) s"
12435:     if ($script:LegacyPS) { try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { } }
12436:     $uri = [Uri]$Url
12437:     $target = $uri
12438:     $useProxy = $false
12439:     try {
12440:         $proxy = [Net.WebRequest]::DefaultWebProxy
12441:         if ($proxy -and -not $uri.IsLoopback -and -not $proxy.IsBypassed($uri)) { $pu = $proxy.GetProxy($uri); if ($pu -and $pu -ne $uri) { $target = $pu; $useProxy = $true } }
12442:     } catch { }
12443:     $probeMs = [int][Math]::Max(100, [Math]::Min($ConnectMs, $TotalMs))
12444:     $tcp = New-Object System.Net.Sockets.TcpClient
12445:     try {
12446:         $ar = $tcp.BeginConnect($target.Host, $target.Port, $null, $null)
12447:         if (-not $ar.AsyncWaitHandle.WaitOne($probeMs)) { $r.Why = "no connection to $($target.Host):$($target.Port) within $([Math]::Round($probeMs / 1000.0, 1)) s"; return $r }
12448:         $tcp.EndConnect($ar)
12449:     } catch {
12450:         $ex = $_.Exception
12451:         while ($ex.InnerException) { $ex = $ex.InnerException }
12452:         $r.Why = "could not connect to $($target.Host):$($target.Port) ($(ConvertTo-OneLine $ex.Message))"
12453:         return $r
12454:     } finally { try { $tcp.Close() } catch { } }
12455:     $left = [int]($TotalMs - $watch.ElapsedMilliseconds)
12456:     if ($left -lt 100) { $r.Why = "no answer within $boundText"; return $r }
