12529: function Invoke-TelemetryPost {
12530:     param([string]$Url, [string]$Body, [int]$ConnectMs = 3000, [int]$TotalMs = 8000)
12531:     return (Invoke-TelemetryRequest -Url $Url -Body $Body -Method 'POST' -ConnectMs $ConnectMs -TotalMs $TotalMs)
