12638: # (wave 28b, D2 / F36-2) The sender's lock <spool>/.flush.lock: a MARKER file {pid, start_time,
12639: # token, since}. (wave 28d, D3 / F48-3, F49-4) BORN WITH ITS OWNER: the record is written to a
12640: # temporary file <lock>.<guid>.tmp (flushed to disk) that is MOVED into place without overwriting - a
12641: # healthy sender never leaves a lock without its owner record, and two senders never both create one.
12642: # An existing lock is refused while somebody holds it open. (wave 28c, D4 / F42-7, F43-5, F44-2) A
12643: # lock whose owner process (pid and start time) lives is NEVER taken over, however old - an owner
12644: # whose identity cannot be confirmed counts as living (Test-PidAlive); it is reported ("sender busy
12645: # since <t>"), and (D3) once it is older than 30 minutes as "sender stuck since <t> (pid <n>)" (Stuck,
12646: # which the flush writes into <spool>/.last `notes`; -Status says it too) with what the operator can
12647: # do. A lock that names no owner or cannot be read counts as HELD while it is younger than 30 s; after
12648: # that - and a lock whose owner is gone at once - it is REMOVED under an exclusive handle (nobody
12649: # rewrites it meanwhile) and the sender starts over (TookOver says why). Released (deleted) in
12650: # `finally` by its owner only (the token); every sender checks its token again right before each spool
12651: # rewrite and each send (Test-TelemetryFlushLockMine).
12652: # { Ok; Token; TookOver ('' or why the old lock was removed); Why (why refused); Stuck ('' or
12653: # "sender stuck since <t> (pid <n>)") }.
12654: $script:TelemetryOwnerlessLockSec = 30
12655: $script:TelemetryStuckLockSec = 1800
12656: function Enter-TelemetryFlushLock {
12657:     param([string]$Path)
12658:     $r = [pscustomobject]@{ Ok = $false; Token = ([guid]::NewGuid().ToString('N')); TookOver = ''; Why = ''; Stuck = '' }
12659:     $content = ConvertTo-Json -Compress -InputObject ([pscustomobject]@{ pid = $PID; start_time = [string](Get-ProcessStartIso -ProcessId $PID); token = $r.Token; since = (Get-IsoTimestamp) })
12660:     $bytes = $script:Utf8NoBom.GetBytes($content + "`n")
12661:     for ($round = 0; $round -lt 3; $round++) {
12662:         # (wave 28d, D3) the record first, in a temporary file; then moved into place only when no lock is there
12663:         $tmp = "$Path.$([guid]::NewGuid().ToString('N')).tmp"
12664:         try {
12665:             $ts = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
12666:             try { $ts.Write($bytes, 0, $bytes.Length); $ts.Flush($true) } finally { $ts.Dispose() }
12667:             $moved = $false
12668:             try { [IO.File]::Move($tmp, $Path); $moved = $true } catch { }
12669:             if ($moved) { $r.Ok = $true; return $r }
12670:         } catch {
12671:             $r.Why = "the lock could not be written ($(ConvertTo-OneLine $_.Exception.Message))"
12672:             return $r
12673:         } finally { try { if ([IO.File]::Exists($tmp)) { [IO.File]::Delete($tmp) } } catch { } }
12674:         # a lock is there: read under an exclusive handle that still lets it be deleted
12675:         $fs = $null
12676:         try { $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Delete) } catch {
12677:             if (-not [IO.File]::Exists($Path)) { continue }
12678:             $r.Why = 'another flush is running (its lock is held)'
12679:             return $r
12680:         }
12681:         $removed = ''
12682:         try {
12683:             $age = ([DateTime]::UtcNow - [IO.File]::GetLastWriteTimeUtc($Path)).TotalSeconds
12684:             $sr = New-Object System.IO.StreamReader($fs, $script:Utf8NoBom, $false, 4096, $true)
12685:             try { $text = $sr.ReadToEnd() } finally { $sr.Dispose() }
12686:             $own = Get-TelemetryFlushLockOwner -Text $text
12687:             $since = $own.Since
12688:             if (-not $since) { $since = [IO.File]::GetLastWriteTimeUtc($Path).ToLocalTime().ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant) }
12689:             if ($own.Owner -eq 'alive') {
12690:                 if ($age -ge $script:TelemetryStuckLockSec) {
12691:                     $r.Stuck = "sender stuck since $since (pid $($own.Pid))"
12692:                     $r.Why = "another flush is running: $($r.Stuck) - its lock is $([int]($age / 60)) min old and its owner lives: it is never taken over; stop pid $($own.Pid) if it hangs, or delete $Path when no such process runs"
12693:                 } else {
12694:                     $r.Why = "another flush is running: sender busy since $since (pid $($own.Pid) holds its lock, $([int]$age) s old$(if ($age -ge $script:TelemetryLockStaleSec) { ' - its owner lives: left alone' }))"
12695:                 }
12696:                 return $r
12697:             }
12698:             if ($own.Owner -eq 'none' -and $age -lt $script:TelemetryOwnerlessLockSec) {
12699:                 $r.Why = "another flush is running (its lock names no owner yet - held while younger than $($script:TelemetryOwnerlessLockSec) s: $([int]$age) s old)"
12700:                 return $r
12701:             }
12702:             $removed = $(if ($own.Owner -eq 'gone') { "its owner pid $($own.Pid) is gone" } else { "it named no owner for $([int]$age) s" })
12703:             # removed under this handle (FileShare.Delete only: nobody writes it meanwhile); then the
12704:             # sender starts over
12705:             [IO.File]::Delete($Path)
12706:         } catch {
12707:             $r.Why = "the lock could not be taken ($(ConvertTo-OneLine $_.Exception.Message))"
12708:             return $r
12709:         } finally { $fs.Dispose() }
12710:         $r.TookOver = $removed
12711:     }
12712:     $r.Why = 'another flush is running (its lock came back each time it was removed)'
12713:     return $r
12714: }
